using UnityEngine;

/// <summary>
/// Pairs each offline prefab with its networked variant (same prefab plus NetworkObject /
/// NetworkTransform / adapters), so gameplay code can keep referencing the offline prefabs
/// and swap in the network one only when <see cref="GameSession.IsOnline"/>. Generated by
/// VRMountainSceneBuilder into Resources so it can be loaded from anywhere.
/// </summary>
[CreateAssetMenu(menuName = "XR Tanks/Network Prefab Map")]
public class NetworkPrefabMap : ScriptableObject
{
    public const string ResourcePath = "XRTanksNetworkPrefabMap";

    [System.Serializable]
    public struct Entry
    {
        public GameObject offline;
        public GameObject online;
    }

    [SerializeField] private Entry[] entries = new Entry[0];

    public Entry[] Entries
    {
        get => entries;
        set => entries = value;
    }

    private static NetworkPrefabMap _instance;

    /// <summary>The network variant of <paramref name="offlinePrefab"/>, or the prefab itself if it has none.</summary>
    public static GameObject Resolve(GameObject offlinePrefab)
    {
        if (offlinePrefab == null)
            return null;

        if (_instance == null)
            _instance = Resources.Load<NetworkPrefabMap>(ResourcePath);
        if (_instance == null)
        {
            Debug.LogError($"[Online] Resources/{ResourcePath} is missing; rebuild the VR scenes.");
            return offlinePrefab;
        }

        foreach (Entry entry in _instance.entries)
        {
            if (entry.offline == offlinePrefab)
                return entry.online;
        }

        Debug.LogError($"[Online] No network variant for '{offlinePrefab.name}'.");
        return offlinePrefab;
    }
}
